import {serializeRoutingExport} from './routing-export.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=(n,d=2)=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const millimetres=n=>Number.isFinite(n)?format(n*1000,2)+' mm':'—';
const xyz=p=>p?.map(n=>format(n,3)).join(', ')||'Not allocated';
const issueName=code=>({'solid-collision':'Object interference','line-collision':'Circuits overlap','self-collision':'Route crosses itself','connector-gap':'Connector gap','connector-tangent':'Connector exit angle','bend-radius':'Bend too tight','length-not-conserved':'Length changes','length-exceeded':'Cut length exceeded','rendered-cap-gap':'Rendered endpoint mismatch','rendered-centerline-mismatch':'Drawn route mismatch','missing-route':'Missing circuit','invalid-obstacle':'Invalid solid record'}[code]||String(code||'Routing issue').replaceAll('-',' '));

export function installRoutingInspector({getScene,context=()=>({}),holdClock=()=>()=>{}}={}){
 const button=document.getElementById('routing-audit-toggle');if(!button)return null;
 const panel=document.createElement('section');panel.id='routing-inspector';panel.className='routing-inspector';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','false');panel.setAttribute('aria-labelledby','routing-inspector-title');
 panel.innerHTML=`<header class="ri-head"><div><span class="ri-kicker">Geometry / current pose</span><h2 id="routing-inspector-title">Harness &amp; hose audit</h2></div><button type="button" class="ri-close" aria-label="Close routing inspector">×</button></header><div class="ri-body"><div class="ri-actions"><button type="button" class="btn ri-refresh">Check current pose</button><button type="button" class="btn ri-download" disabled>Download JSON</button></div><div class="ri-state" role="status" aria-live="polite"></div><div class="ri-results"></div></div>`;
 document.body.append(panel);const primary=document.getElementById('primary'),state=panel.querySelector('.ri-state'),results=panel.querySelector('.ri-results'),download=panel.querySelector('.ri-download'),refresh=panel.querySelector('.ri-refresh');let worker=null,requestId=0,report=null,snapshot=null,release=null,selected=null,query='',onlyIssues=false;
 function stop(){requestId++;worker?.terminate();worker=null;refresh.disabled=false;}
 function close(){stop();panel.hidden=true;primary?.classList.remove('routing-audit-open');button.setAttribute('aria-expanded','false');getScene()?.highlightRouting?.(null);release?.();release=null;button.focus();}
 function rows(){
  const all=(report?.routes||[]).filter(r=>(!onlyIssues||r.issues.length)&&(!query||(r.id+' '+r.label+' '+r.scope+' '+r.sectionIds.join(' ')+' '+r.issues.map(i=>i.obstacleId||'').join(' ')).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.issues.length-a.issues.length||a.id.localeCompare(b.id));
  const table=panel.querySelector('.ri-route-rows');if(!table)return;table.innerHTML=all.map(r=>`<tr class="${r.issues.length?'ri-row-issue':''}${selected===r.id?' ri-selected':''}"><td><button type="button" data-routing-route="${escape(r.id)}"><span class="ri-dot ${r.issues.length?'ri-dot-issue':''}"></span><span>${escape(r.label)}<small>${escape(r.scope)}${r.label!==r.id?' · '+escape(r.id):''}</small></span></button></td><td>${format(r.lengthM)}<small>m</small></td><td>${r.minimumBendRadiusM===Infinity?'Straight':format(r.minimumBendRadiusM*1000,1)}<small>${r.sectionBendLimits.length>1?'mm · section limits':r.minimumBendRadiusM===Infinity?'':(Number.isFinite(r.requiredBendRadiusM)?'mm / '+format(r.requiredBendRadiusM*1000,1)+' min':'mm · allocation open')}</small></td><td>${r.issues.length?'<b>'+r.issues.length+'</b>':'Clear'}</td></tr>`).join('')||'<tr><td colspan="4" class="ri-empty">No circuits match this filter.</td></tr>';
  panel.querySelector('.ri-filter-count').textContent=all.length+' of '+report.routes.length+' circuits';
 }
 function details(id){
  selected=id;const route=report?.routes.find(r=>r.id===id),host=panel.querySelector('.ri-detail');if(!route||!host)return;const highlighted=getScene()?.highlightRouting?.(id);rows();
  const items=route.issues.map(issue=>{const object=issue.obstacleId?report.obstacleLabels[issue.obstacleId]||issue.obstacleId:issue.otherRouteId||'',measure=Number.isFinite(issue.clearanceM)?' · clearance '+millimetres(issue.clearanceM):Number.isFinite(issue.gapM)?' · gap '+millimetres(issue.gapM):'';return '<li><b>'+escape(issueName(issue.code))+'</b>'+ (object?'<span>'+escape(object)+'</span>':'')+escape(measure)+'</li>';}).join('');
  const sectionLimits=route.sectionBendLimits.length>1?'<details class="ri-sections"><summary>'+route.sectionBendLimits.length+' section bend allocations</summary>'+route.sectionBendLimits.map(s=>'<p><code>'+escape(s.id)+'</code><span>'+ (s.minimumBendRadiusM===Infinity?'Straight':millimetres(s.minimumBendRadiusM))+' · allocated '+(s.requiredBendRadiusM?millimetres(s.requiredBendRadiusM):'straight section')+'</span></p>').join('')+'</details>':'';
  host.innerHTML=`<div class="ri-detail-heading"><span class="ri-kicker">${highlighted?'Highlighted in gold':'Switch to Spacecraft to see the route'}</span><h3>${escape(route.label)}</h3><code>${escape(route.id)}</code></div><dl><div><dt>Tube diameter</dt><dd>${millimetres(route.radiusM*2)}</dd></div><div><dt>Drawn length</dt><dd>${format(route.lengthM,4)} m</dd></div><div><dt>Minimum bend</dt><dd>${route.minimumBendRadiusM===Infinity?'Straight':millimetres(route.minimumBendRadiusM)}</dd></div><div><dt>Allocated bend</dt><dd>${route.sectionBendLimits.length>1?'Per section':millimetres(route.requiredBendRadiusM)}</dd></div><div><dt>Start gap</dt><dd>${millimetres(route.fromGapM)}</dd></div><div><dt>End gap</dt><dd>${millimetres(route.toGapM)}</dd></div>${route.restLengthM!==null?'<div><dt>Rest length</dt><dd>'+format(route.restLengthM,4)+' m</dd></div>':''}</dl><div class="ri-endpoints"><span>Start · ${escape(xyz(route.from))} m</span><span>End · ${escape(xyz(route.to))} m</span></div>${items?'<ul class="ri-issue-list">'+items+'</ul>':'<p class="ri-clear-note">No interference, endpoint or bend finding for this circuit at the captured pose.</p>'}${sectionLimits}`;
 }
 function show(result){
  report=result;download.disabled=false;const c=result.context||{},label=c.label||c.design||'Current spacecraft',stateClass=result.routes.length?(result.ok?'ri-good':'ri-bad'):'ri-neutral';state.className='ri-state '+stateClass;state.innerHTML=`<strong>${!result.routes.length?'No routed model available':result.ok?'Clear at this pose':'Routing needs correction'}</strong><span>${escape(label)}${Number.isFinite(c.timeS)?' · MET '+format(c.timeS,1)+' s':''}</span>`;
  results.innerHTML=`<div class="ri-stats"><div><b>${result.routes.length}</b><span>Circuits</span></div><div><b>${result.counts.obstacles}</b><span>Physical solids</span></div><div><b>${result.issueCount}</b><span>Findings</span></div></div><p class="ri-scope"><b>Captured routing geometry</b> · Drawn tube buffers, full radius, connector exits and physical walls. Conservative swept envelopes also reserve every CMG and terminal pointing angle. The flight clock is held while this inspector is open.</p><div class="ri-sweep"><span class="ri-kicker">Preliminary movement review</span><p>This result describes the captured pose. Use the deployment controls to inspect stowed, moving and deployed arrangements, including slack and intended routing space. Selected poses support a preliminary movement review; continuous motion and repeated-flex life require separate evidence. CMG and terminal envelopes reserve their operating angles.</p></div><div class="ri-filter"><label><span class="sr-only">Filter circuits or solid IDs</span><input type="search" placeholder="Find a circuit or solid ID…" value="${escape(query)}" class="ri-search"></label><label class="ri-only"><input type="checkbox" class="ri-only-issues" ${onlyIssues?'checked':''}> Findings only</label></div><div class="ri-table-meta"><span class="ri-filter-count"></span><span>Min. clearance ${millimetres(result.minimumClearanceM)}</span></div><div class="ri-table-wrap"><table><thead><tr><th>Circuit</th><th>Length</th><th>Bend</th><th>Pose</th></tr></thead><tbody class="ri-route-rows"></tbody></table></div><div class="ri-detail"><p class="ri-empty">Select a circuit to highlight its route and inspect its endpoints.</p></div>${result.truncated?'<p class="ri-truncated">The detailed finding list is limited; the total finding count remains complete.</p>':''}<p class="ri-footnote">Geometry allocations remain preliminary. Cable or hose part selection, mounting tolerances and repeated-flex qualification require their own evidence.</p>`;
  const electrical=c.installedElectricalAccounting;
  if(electrical){
   const masses=Object.entries(electrical.massAccounting||{}),adopted=['installed-route-mass-adopted','model-estimate-adopted'].includes(electrical.status),installed=electrical.status==='installed-route-mass-adopted';
   const shortfall=masses.some(([,m])=>Number.isFinite(m.estimatedRequiredKg)&&Number.isFinite(m.allocatedKg)&&m.estimatedRequiredKg>m.allocatedKg+1e-8);
   const massRows=masses.map(([id,m])=>{const name=id==='07.05'?'Flight harnesses and terminations':id==='01.04'?'Payload data harnesses':m.parentId||id,gap=m.estimatedRequiredKg-m.allocatedKg;return '<div><dt>'+escape(name)+'</dt><dd>'+(adopted&&!shortfall?format(m.allocatedKg)+' kg included':format(m.estimatedRequiredKg)+' kg estimated / '+format(m.allocatedKg)+' kg allocated'+(Number.isFinite(gap)?'<br><small>'+format(Math.abs(gap))+' kg '+(gap>0?'shortfall':'allocated margin')+'</small>':''))+'</dd></div>';}).join('');
   const basis=adopted?(installed?'Individual installed cable cuts':'Current preliminary route estimates')+', conductor construction and endpoint terminations set these masses. They are included once in the master equipment list and vehicle totals; the vehicle dry-growth allowance is applied separately.':'These estimates use the installed routes, current conductor choices and termination allowances.';
   const installation=electrical.installationHardwareCount?'<div><dt>Mounted cable-installation hardware</dt><dd>'+format(electrical.installationHardwareMassKg)+' kg · '+format(electrical.installationHardwareCount,0)+' individual MEL assemblies</dd></div>':'';
   const optics=electrical.workerOptics?.moduleCount?'<div><dt>Worker-link optical modules</dt><dd>'+format(electrical.workerOptics.massKg)+' kg · '+format(electrical.workerOptics.moduleCount,0)+' modules · '+format(electrical.workerOptics.powerW,1)+' W</dd></div>':'';
   results.insertAdjacentHTML('beforeend',`<details class="ri-sections" open><summary>Electrical harness mass · ${shortfall?'accounting discrepancy':adopted?'included in vehicle totals':'preliminary'}</summary><dl><div><dt>Individual harnesses</dt><dd>${format(electrical.harnessCount||0,0)} assemblies · ${format(electrical.cableRunCount||0,0)} cable runs</dd></div><div><dt>Physical cable cut length</dt><dd>${format(electrical.totalCableLengthM)} m</dd></div><div><dt>Calculated power-circuit loss</dt><dd>${format(electrical.powerLossW)} W</dd></div>${massRows}${installation}${optics}${adopted?'<div><dt>Vehicle dry / wet mass</dt><dd>'+format(electrical.dryKg)+' / '+format(electrical.wetKg)+' kg</dd></div><div><dt>Launch mass with adapter</dt><dd>'+format(electrical.launchKg)+' kg</dd></div>':''}</dl><p>${basis} Individual harness IDs, endpoints, cuts and mass are available in the master equipment list. Mounted hardware and optical modules have their own accounted rows.</p></details>`);
  }
  const transfer=c.rotaryElectricalAccounting;
  if(transfer){
   const mapping=[...(transfer.powerCircuits||[]),...(transfer.opticalLinks||[])].map(item=>'<tr><td>'+escape(item.id)+'</td><td>'+escape(item.upstreamHarnessId)+' → '+escape(item.statorPortId)+'</td><td>'+escape(item.rotorPortId)+' → '+escape(item.downstreamHarnessId)+'</td></tr>').join('');
   results.insertAdjacentHTML('beforeend',`<details class="ri-sections" open><summary>${escape(transfer.componentLabel||'Hinge-axis power and fiber transfer')}</summary><dl><div><dt>Installed channels</dt><dd>${format(transfer.powerPasses,0)} power paths · ${format(transfer.opticalChannels,0)} optical fibers</dd></div><div><dt>Power current per circuit</dt><dd>${format(transfer.requiredCurrentPerBranchA)} A required / ${format(transfer.allocatedCurrentPerBranchA)} A allocated</dd></div><div><dt>Rotary transfer dissipation</dt><dd>${format(transfer.rotaryLossW)} W · included in circuit loss</dd></div><div><dt>Worst complete optical path</dt><dd>${format(transfer.opticalTotalLinkLossDb,3)} dB / ${format(transfer.opticalLinkBudgetDb,2)} dB budget</dd></div><div><dt>Optical margin</dt><dd>${format(transfer.opticalMarginDb,3)} dB</dd></div></dl><p>Fixed harnesses end on the stator; separate platform harnesses start on the rotor and follow mounted ladder trays. Explicit internal power and optical channels join those ports. Contacts and contained leads enter the power model; the optical budget includes both cable sections, mating pairs, rotary loss and the aging allocation.</p><p>This is a custom preliminary spacecraft assembly using documented rotary-joint and optical-interface capability classes. Its allocated limits remain distinct from flight qualification.</p><details><summary>Electrical and optical circuit mapping</summary><div class="ri-table-wrap"><table><thead><tr><th>Circuit</th><th>Fixed side</th><th>Moving side</th></tr></thead><tbody>${mapping}</tbody></table></div></details></details>`);
  }
  const rotary=c.rotaryFluidAccounting;
  if(rotary?.channelCount){const pressure=Number.isFinite(rotary.nominalPressureDropPa)?format(rotary.nominalPressureDropPa/1000,2)+' kPa at nominal flow':'Unclosed: working fluid and flow',mass=rotary.hardwareMassKg??rotary.allocatedMassKg;
   results.insertAdjacentHTML('beforeend',`<details class="ri-sections"><summary>Rotary fluid interfaces · project allocations</summary><dl><div><dt>Channel paths</dt><dd>${escape(rotary.channelCount)}</dd></div><div><dt>Allocated hardware</dt><dd>${format(mass,2)} kg</dd></div><div><dt>Minimum flow bore</dt><dd>${millimetres(rotary.minimumFlowDiameterM)}</dd></div><div><dt>Calculated rotary loss</dt><dd>${escape(pressure)}</dd></div></dl><p>${escape(rotary.hydraulicClosure||'The rotary passage and feeder pressure loss, fluid inventory and thermal capacity enter the shared fluid-loop model. These are calculated project budgets.')}</p><p>Supplier evidence remains open for bore, installed mass, pressure loss, working and proof pressure, leakage, fluid compatibility, torque and repeated rotation life. A clear geometry result does not close those requirements.</p></details>`);
  }
  const lengths=c.installedFluidLengthAccounting;
  if(lengths?.rows?.length)results.insertAdjacentHTML('beforeend',`<details class="ri-sections"><summary>Installed fluid lengths · ${lengths.reconciliationClosed?'ledger':'network reconciliation open'}</summary><dl><div><dt>Drawn coolant pipes</dt><dd>${format(lengths.actualExternalCoolantLengthM,2)} m</dd></div><div><dt>Drawn propellant pipes</dt><dd>${format(lengths.actualPropellantLengthM,2)} m</dd></div><div><dt>Model header allocation</dt><dd>${format(lengths.modeledLengthsM?.header,2)} m</dd></div><div><dt>Model branch allocation</dt><dd>${format(lengths.modeledLengthsM?.branch,2)} m</dd></div><div><dt>Recorded sections</dt><dd>${lengths.rows.length}</dd></div></dl><p>${escape(lengths.basis)}</p>${lengths.shortfall?'<p>'+escape(lengths.shortfall)+'</p>':''}<p>The JSON download includes each measured section and its retained developed-length construction.</p></details>`);
  rows();if(selected&&report.routes.some(r=>r.id===selected))details(selected);
 }
 async function inspect(){
  stop();report=null;snapshot=null;download.disabled=true;refresh.disabled=true;state.className='ri-state ri-neutral';state.innerHTML='<strong>Checking the current geometry…</strong><span>Reading actual tube buffers and physical solids.</span>';results.innerHTML='';const id=requestId;
  await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(id!==requestId)return;
  try{const scene=getScene();if(!scene?.getRoutingSnapshot)throw new Error('The 3D model is still preparing. Try again when the flight view is ready.');snapshot=scene.getRoutingSnapshot();snapshot.context={...context(),...snapshot.context};if(id!==requestId)return;
   const finish=result=>{if(id!==requestId)return;refresh.disabled=false;show(result);worker?.terminate();worker=null;};
   if(typeof Worker==='function'){worker=new Worker(new URL('./routing-audit-worker.js',import.meta.url),{type:'module'});worker.onmessage=event=>{if(event.data.id!==id)return;if(event.data.error){state.textContent=event.data.error;refresh.disabled=false;stop();return;}finish(event.data.result);};worker.onerror=event=>{state.textContent='Routing check could not finish: '+event.message;stop();};worker.postMessage({id,snapshot});}
   else{const {inspectRoutingSnapshot}=await import('./routing-audit-worker.js');finish(inspectRoutingSnapshot(snapshot));}
  }catch(error){state.className='ri-state ri-bad';state.textContent=error.message;refresh.disabled=false;}
 }
 button.setAttribute('aria-controls',panel.id);button.setAttribute('aria-expanded','false');button.addEventListener('click',()=>{if(!panel.hidden){close();return;}if(primary){primary.append(panel);panel.classList.add('ri-docked');primary.classList.add('routing-audit-open');}panel.hidden=false;button.setAttribute('aria-expanded','true');release=holdClock();primary?.scrollIntoView({block:'start',behavior:'auto'});panel.querySelector('.ri-close').focus({preventScroll:true});inspect();});panel.querySelector('.ri-close').addEventListener('click',close);refresh.addEventListener('click',inspect);
 panel.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();close();}});panel.addEventListener('click',event=>{const route=event.target.closest('[data-routing-route]');if(route)details(route.dataset.routingRoute);});panel.addEventListener('input',event=>{if(event.target.matches('.ri-search')){query=event.target.value;rows();}if(event.target.matches('.ri-only-issues')){onlyIssues=event.target.checked;rows();}});
 download.addEventListener('click',()=>{if(!report||!snapshot)return;const blob=new Blob([serializeRoutingExport({schema:'orbital-routing-pose-audit-v1',report,snapshot})],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='routing-pose-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 return {close,destroy(){close();panel.remove();}};
}
